select.if:
WITH LOT_DATA AS ( SELECT T.TECH , T.PRODG1 , T.PRODSPEC_ID , T.LOCATION_FAB , T.FAB , T.LAYER , T.NENG_FLAG , T.LOT_ID , T.WAFER_QTY , T.LOT_PROC_STATE , T.CUR_OPE_NO , T.OPE_NO , DECODE(T.CUR_OPE_NO ,T.OPE_NO,'当站','Coming') AS WIP_CATEGORY , TO_CHAR(T.FCST_TIME, 'YYYY-MM-DD HH24:MM:SS') AS FCST_TIME , T.FCST_SHIFT_DATE , T.CLOSE_HOUR , T.SGS_GROUP , T.SGS_EQP , T.MAINPD_ID , T.STD_CT_END , T.MIN_STD_TIME , T.SGS_FIRST_OP , T.INLINE_CYC_ACC , ROW_NUMBER() OVER(PARTITION BY T.LOT_ID ORDER BY T.OPE_SEQ) RN FROM A1MFG.PR_SGS_EQP_WIP T WHERE 1=1 AND T.SGS_EQP = #{eqpid}
AND T.TECH = #{tech}
AND T.SGS_GROUP = #{sgsgroup} AND T.OPE_NO = #{openo}
AND T.NENG_FLAG LIKE '%'
AND T.NENG_FLAG =#{neng}
) SELECT A.LOCATION_FAB , A.FAB , A.TECH , A.PRODG1 , A.PRODSPEC_ID , A.LOT_ID , A.WAFER_QTY , A.NENG_FLAG , TO_NUMBER(B.LOT_PRIORITY) AS LOT_PRIORITY , A.LOT_PROC_STATE , A.CUR_OPE_NO , A.OPE_NO , A.WIP_CATEGORY , A.CLOSE_HOUR , A.SGS_GROUP , A.SGS_EQP , A.FCST_SHIFT_DATE , A.FCST_TIME FROM LOT_DATA A LEFT JOIN PWEB.A3_LOT_PRIORITY B ON A.PRODG1 = B.PRODG1 AND A.LOT_ID =B.LOT_ID WHERE A.RN = 1 AND A.WIP_CATEGORY ='当站' ORDER BY A.PRODG1, A.CUR_OPE_NO

WITH LOT_DATA AS ( SELECT T.TECH , T.PRODG1 , T.PRODSPEC_ID , T.LOCATION_FAB , T.FAB , T.LAYER , T.NENG_FLAG , T.LOT_ID , T.WAFER_QTY , T.LOT_PROC_STATE , T.CUR_OPE_NO , T.OPE_NO , DECODE(T.CUR_OPE_NO ,T.OPE_NO,'当站','Coming') AS WIP_CATEGORY , TO_CHAR(T.FCST_TIME, 'YYYY-MM-DD HH24:MM:SS') AS FCST_TIME , T.FCST_SHIFT_DATE , T.CLOSE_HOUR , T.SGS_GROUP , T.SGS_EQP , T.MAINPD_ID , T.STD_CT_END , T.MIN_STD_TIME , T.SGS_FIRST_OP , T.INLINE_CYC_ACC , ROW_NUMBER() OVER(PARTITION BY T.LOT_ID ORDER BY T.OPE_SEQ) RN FROM A1MFG.PR_SGS_EQP_WIP T WHERE 1=1 AND T.SGS_EQP = #{eqpid}
AND T.TECH = #{tech}
AND T.SGS_GROUP = #{sgsgroup}
AND T.NENG_FLAG LIKE '%'
AND T.NENG_FLAG =#{neng}
) SELECT A.LOCATION_FAB , A.FAB , A.TECH , A.PRODG1 , A.PRODSPEC_ID , A.LOT_ID , A.WAFER_QTY , A.NENG_FLAG , TO_NUMBER(B.LOT_PRIORITY) AS LOT_PRIORITY , A.LOT_PROC_STATE , A.CUR_OPE_NO , A.OPE_NO , A.WIP_CATEGORY , A.CLOSE_HOUR , A.SGS_GROUP , A.SGS_EQP , A.FCST_SHIFT_DATE , A.FCST_TIME FROM LOT_DATA A LEFT JOIN PWEB.A3_LOT_PRIORITY B ON A.PRODG1 = B.PRODG1 AND A.LOT_ID =B.LOT_ID WHERE A.RN = 1 AND A.WIP_CATEGORY ='Coming'
AND A.OPE_NO = #{openo}
ORDER BY A.PRODG1, A.CUR_OPE_NO

